def start(tag, rdb, overrides):
    """Fresh private dir holding only a copy of this one RDB; load it as dbfilename."""
    d = os.path.join(RUN, tag)
    shutil.rmtree(d, ignore_errors=True)
    os.makedirs(d)
    shutil.copyfile(os.path.join(SRC, rdb), os.path.join(d, rdb))

    log = os.path.join(LOGS, tag + ".log")
    cmd = [BIN, "--dir", d, "--dbfilename", rdb, "--port", str(PORT),
           "--bind", "127.0.0.1", "--save", "", "--appendonly", "no",
           "--logfile", log, "--daemonize", "no"]
    for k, v in overrides.items():
        cmd += ["--" + k, str(v)]

    p = subprocess.Popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    for _ in range(200):
        if p.poll() is not None:
            raise RuntimeError("%s: server exited %s; log:\n%s"
                               % (tag, p.returncode, open(log).read()))
