            c = R("127.0.0.1", PORT)
            if c.cmd("PING") == "PONG":
                return p, c, d
            c.close()
        except (OSError, EOFError):
            time.sleep(0.05)
    raise RuntimeError("%s: server never answered PING; log:\n%s" % (tag, open(log).read()))


