#!/usr/bin/env python3
"""Load each historical RDB under Redis 7.2 twice (default limits, then with the
compact-encoding limit forced to 1) and record TYPE / OBJECT ENCODING / payload."""
import hashlib, json, os, shutil, socket, subprocess, time

SRC = "/data/rdb"
BIN = "/app/src/redis-server"
RUN = "/work/run"
LOGS = "/work/logs"
PORT = 6480

# (rdb basename, payload key, config knob tightened to 1)
CASES = [
    ("hash-zipmap.rdb", "hash", "hash-max-listpack-entries"),
    ("hash-ziplist.rdb", "hash", "hash-max-listpack-entries"),
    ("zset-ziplist.rdb", "zset", "zset-max-listpack-entries"),
    ("list-quicklist.rdb", "list", "list-max-listpack-size"),
]


class R:
    """Minimal RESP client so replies are parsed unambiguously."""

    def __init__(self, host, port):
        self.s = socket.create_connection((host, port), timeout=10)
        self.f = self.s.makefile("rb")

    def cmd(self, *args):
        out = b"*%d\r\n" % len(args)
        for a in args:
            if isinstance(a, str):
                a = a.encode()
            out += b"$%d\r\n%s\r\n" % (len(a), a)
        self.s.sendall(out)
        return self.read()

    def read(self):
        line = self.f.readline()
        if not line:
            raise EOFError("connection closed")
        t, body = line[:1], line[1:-2]
        if t == b"+":
            return body.decode()
        if t == b"-":
            raise RuntimeError(body.decode())
        if t == b":":
            return int(body)
        if t == b"$":
            n = int(body)
            return None if n == -1 else self.f.read(n + 2)[:n].decode("utf-8")
        if t == b"*":
            n = int(body)
            return None if n == -1 else [self.read() for _ in range(n)]
        raise RuntimeError("unexpected RESP line: %r" % line)

    def close(self):
        try:
            self.f.close()
            self.s.close()
        except OSError:
            pass
